#!/usr/bin/env node
/**
 * 审计 env 分发：对比 SSOT 生成物、manifest 冲突、跨 target 一致性。
 */
import fs from "node:fs";
import path from "node:path";
import {
  REPO_ROOT,
  buildTargetContent,
  loadManifest,
  loadProfileValues,
  parseEnvFile,
  resolveTargetValue,
} from "./lib.mjs";

const PROFILE_TARGETS = {
  local: [".env.api.local", ".env.web.local", ".env.web.cloudflare"],
  production: [
    ".env.api.production",
    ".env.web.production",
    ".env.trigger.production",
    ".env.web.cloudflare.production",
  ],
};

function collectIssues() {
  const manifest = loadManifest();
  const issues = { errors: [], warnings: [], info: [] };

  for (const [profile, profileConfig] of Object.entries(manifest.profiles ?? {})) {
    const sharedValues = loadProfileValues(profile);
    const targets = profileConfig.targets ?? {};

    for (const [targetName, targetConfig] of Object.entries(targets)) {
      const keys = targetConfig.keys ?? [];
      const keySet = new Set();
      for (const key of keys) {
        if (keySet.has(key)) {
          issues.errors.push(`${profile}/${targetName}: duplicate key in keys list: ${key}`);
        }
        keySet.add(key);
        const value = resolveTargetValue(key, sharedValues, targetConfig.overrides ?? {});
        if (value === undefined) {
          issues.errors.push(`${profile}/${targetName}: missing value for ${key}`);
        }
      }

      const absolutePath = path.join(REPO_ROOT, targetName);
      if (!fs.existsSync(absolutePath)) {
        issues.errors.push(`${targetName}: file missing on disk`);
        continue;
      }

      const expected = buildTargetContent(targetName, targetConfig, sharedValues);
      const onDisk = fs.readFileSync(absolutePath, "utf8").replace(/\r\n/g, "\n");
      const expectedNorm = expected.replace(/\r\n/g, "\n");

      if (onDisk.startsWith("# GENERATED BY pnpm env:sync")) {
        if (onDisk !== expectedNorm) {
          issues.errors.push(`${targetName}: disk content !== SSOT (run pnpm env:sync)`);
        }
      } else {
        const exp = parseEnvFile(expected).entries;
        const disk = parseEnvFile(onDisk).entries;
        for (const key of keys) {
          if (exp[key] !== disk[key]) {
            issues.warnings.push(
              `${targetName}: legacy file, key ${key} differs from SSOT`,
            );
          }
        }
        for (const key of Object.keys(disk)) {
          if (!keySet.has(key)) {
            issues.warnings.push(
              `${targetName}: key ${key} on disk but not in manifest (orphan)`,
            );
          }
        }
      }
    }

    // 同一 profile 内：同一 key 出现在多个 target 时，值是否一致（除 overrides 显式允许外）
    const keyToTargets = new Map();
    for (const [targetName, targetConfig] of Object.entries(targets)) {
      for (const key of targetConfig.keys ?? []) {
        const value = resolveTargetValue(key, sharedValues, targetConfig.overrides ?? {});
        if (!keyToTargets.has(key)) {
          keyToTargets.set(key, []);
        }
        keyToTargets.get(key).push({ target: targetName, value });
      }
    }
    for (const [key, entries] of keyToTargets) {
      if (entries.length < 2) continue;
      const distinct = [...new Set(entries.map((e) => e.value))];
      if (distinct.length > 1) {
        const detail = entries.map((e) => `${e.target}=${JSON.stringify(e.value)}`).join("; ");
        issues.info.push(
          `${profile}: key ${key} intentionally differs across targets: ${detail}`,
        );
      }
    }
  }

  return issues;
}

function compareImportBaseline() {
  const warnings = [];
  const manifest = loadManifest();

  for (const [profile, files] of Object.entries(PROFILE_TARGETS)) {
    const profileConfig = manifest.profiles?.[profile];
    if (!profileConfig) {
      warnings.push(`Profile ${profile} missing in manifest`);
      continue;
    }
    const sharedValues = loadProfileValues(profile);

    for (const relativePath of files) {
      const targetConfig = profileConfig.targets?.[relativePath];
      if (!targetConfig) {
        warnings.push(`${profile}: manifest has no target ${relativePath}`);
        continue;
      }

      const absolutePath = path.join(REPO_ROOT, relativePath);
      if (!fs.existsSync(absolutePath)) {
        warnings.push(`${relativePath}: missing`);
        continue;
      }

      const generated = parseEnvFile(
        buildTargetContent(relativePath, targetConfig, sharedValues),
      ).entries;

      // 若存在 .env.bak 可对比；否则用当前磁盘（已是 generated）
      const disk = parseEnvFile(fs.readFileSync(absolutePath, "utf8")).entries;

      for (const key of Object.keys(disk)) {
        if (!targetConfig.keys.includes(key)) {
          warnings.push(
            `${relativePath}: disk has key ${key} not listed in manifest keys`,
          );
        }
      }
      for (const key of targetConfig.keys) {
        if (!(key in disk)) {
          warnings.push(`${relativePath}: manifest lists ${key} but missing on disk`);
        }
      }
    }
  }

  return warnings;
}

function findOrphanValues(manifest) {
  const warnings = [];
  for (const [profile, profileConfig] of Object.entries(manifest.profiles ?? {})) {
    const sharedValues = loadProfileValues(profile);
    const usedKeys = new Set();
    for (const targetConfig of Object.values(profileConfig.targets ?? {})) {
      for (const key of targetConfig.keys ?? []) {
        usedKeys.add(key);
      }
    }
    for (const key of Object.keys(sharedValues)) {
      if (!usedKeys.has(key)) {
        warnings.push(`${profile}: values.${key} is not referenced by any target keys list`);
      }
    }
  }
  return warnings;
}

function findSharedTargetMismatches(manifest) {
  const warnings = [];
  const pairs = [
    ["local", ".env.api.local", ".env.web.local"],
    ["production", ".env.api.production", ".env.web.production"],
  ];

  for (const [profile, apiPath, webPath] of pairs) {
    const profileConfig = manifest.profiles?.[profile];
    if (!profileConfig) continue;
    const sharedValues = loadProfileValues(profile);
    const apiTarget = profileConfig.targets?.[apiPath];
    const webTarget = profileConfig.targets?.[webPath];
    if (!apiTarget || !webTarget) continue;

    const sharedKeys = apiTarget.keys.filter((key) => webTarget.keys.includes(key));
    for (const key of sharedKeys) {
      const apiValue = resolveTargetValue(key, sharedValues, apiTarget.overrides ?? {});
      const webValue = resolveTargetValue(key, sharedValues, webTarget.overrides ?? {});
      if (apiValue !== webValue) {
        warnings.push(
          `${profile}: api/web disagree on ${key} (should usually match for secrets and CREEM_SUBSCRIPTIONS)`,
        );
      }
    }
  }

  return warnings;
}

function main() {
  const manifest = loadManifest();
  const issues = collectIssues();
  const baseline = compareImportBaseline();
  issues.warnings.push(...findOrphanValues(manifest));
  issues.warnings.push(...findSharedTargetMismatches(manifest));

  console.log("=== env audit ===\n");

  if (issues.errors.length) {
    console.log("ERRORS:");
    for (const e of issues.errors) console.log(`  [E] ${e}`);
    console.log("");
  }

  if (issues.warnings.length || baseline.length) {
    console.log("WARNINGS:");
    for (const w of [...issues.warnings, ...baseline]) console.log(`  [W] ${w}`);
    console.log("");
  }

  if (issues.info.length) {
    console.log("CROSS-TARGET DIFFS (expected when overrides differ):");
    for (const i of issues.info) console.log(`  [I] ${i}`);
    console.log("");
  }

  if (!issues.errors.length && !issues.warnings.length && !baseline.length) {
    console.log("No errors or warnings. SSOT matches manifest and on-disk generated files.");
  }

  console.log(
    `\nSummary: ${issues.errors.length} error(s), ${issues.warnings.length + baseline.length} warning(s), ${issues.info.length} cross-target diff(s).`,
  );

  if (issues.errors.length) process.exit(1);
}

main();
